{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this decision — are you trying to maximize total profit (revenue from selling the animals minus feed costs), maximize total revenue, or minimize total feed cost?"
  ],
  "rationale": "The response asks for a single policy choice among three mutually exclusive objective functions, which constitutes one semantically independent clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the profit calculated as a one-time sale (i.e., you sell each animal once and the profit is selling price minus feed cost for that animal), or is it an ongoing daily/period profit where feed cost is incurred continuously while the animals are kept?"
  ],
  "rationale": "The response asks for a single policy choice between two mutually exclusive calculation methods, which constitutes one semantically independent question."
}

{
  "action": "question",
